"<div class=\"route\"><div><b>⇄ {0}</b> <span class=\"muted\">{1} ly ・ Lv{2} (輸送船 {3} 隻・片道 {4}/年。量は質量 100 万 t)</span> <span class=\"{5}\">稼働率 {6}</span><br>\n      <span class=\"muted\">送り {7}/年 ・ 受け取り {8}/年</span></div>\n      {9}</div>": "<div class=\"route\"><div><b>⇄ {0}</b> <span class=\"muted\">{1} ly · Lv{2} ({3} transports, {4}/yr each way; volumes in million tonnes)</span> <span class=\"{5}\">Utilization {6}</span><br>\n      <span class=\"muted\">Out {7}/yr · in {8}/yr</span></div>\n      {9}</div>",
