"<label class=\"field\">歩兵を呼び寄せる (交易路経由)\n      <select data-act=\"torigin\">{0}</select></label>\n    <div class=\"btns\"><button data-act=\"troopsend\" data-from=\"{1}\" data-to=\"{2}\" data-n=\"1\">1連隊</button><button data-act=\"troopsend\" data-from=\"{3}\" data-to=\"{4}\" data-n=\"all\">全部隊</button></div>": "<label class=\"field\">Call in troops (via trade routes)\n      <select data-act=\"torigin\">{0}</select></label>\n    <div class=\"btns\"><button data-act=\"troopsend\" data-from=\"{1}\" data-to=\"{2}\" data-n=\"1\">1 regiment</button><button data-act=\"troopsend\" data-from=\"{3}\" data-to=\"{4}\" data-n=\"all\">All units</button></div>",
