"<tr><td>{0} ⇄ {1}</td><td>{2} ly</td><td>Lv{3} <span class=\"muted\">(輸送船 {4} 隻・{5}/年)</span></td>\n      <td>{6}/年</td><td>{7}/年</td><td class=\"{8}\">{9}</td>\n      <td>{10}</td><td>{11}</td>\n      <td>{12}</td></tr>": "<tr><td>{0} ⇄ {1}</td><td>{2} ly</td><td>Lv{3} <span class=\"muted\">({4} ships · {5}/yr)</span></td>\n      <td>{6}/yr</td><td>{7}/yr</td><td class=\"{8}\">{9}</td>\n      <td>{10}</td><td>{11}</td>\n      <td>{12}</td></tr>",
