"<tr class=\"{0}{1}\"><td><button data-act=\"gobody\" data-sys=\"{2}\" data-body=\"{3}\">{4}{5}</button>{6}{7}<div class=\"send\">{8}</div></td>\n      <td data-l=\"首都から\">{9} ly</td><td data-l=\"種類\">{10}{11}</td>\n      <td data-l=\"入植適性\">{12}</td>\n      <td data-l=\"環境\">{13}{14} g{15}</td>\n      <td data-l=\"先住民\">{16}</td><td data-l=\"資源\">{17}</td></tr>": "<tr class=\"{0}{1}\"><td><button data-act=\"gobody\" data-sys=\"{2}\" data-body=\"{3}\">{4}{5}</button>{6}{7}<div class=\"send\">{8}</div></td>\n      <td data-l=\"From capital\">{9} ly</td><td data-l=\"Type\">{10}{11}</td>\n      <td data-l=\"Suitability\">{12}</td>\n      <td data-l=\"Environment\">{13}{14} g{15}</td>\n      <td data-l=\"Natives\">{16}</td><td data-l=\"Resources\">{17}</td></tr>",
