"<section><h3>銀河</h3>\n      <div class=\"row\"><label>星間マップ <select id=\"home-galaxy\"><option value=\"real\" {0}>実在の星 (既定)</option><option value=\"gen\" {1}>自動生成</option></select></label></div>\n      <div class=\"row\"><label>銀河の番号 <input id=\"home-seed\" type=\"text\" inputmode=\"numeric\" placeholder=\"空欄ならランダム\" value=\"{2}\"></label>\n        <label><input id=\"home-spectate\" type=\"checkbox\" {3}> 観戦モード</label></div>\n      {4}</section>\n    <section><h3>国</h3>\n      <div class=\"row\"><label>国の数 <select id=\"home-nat\">{5}</select></label>\n        <label>難易度 <select id=\"home-hc\">{6}</select></label></div>\n      {7}\n      {8}</section>\n    <section><h3>経済</h3>\n      <div class=\"row\"><label>生産性 <select id=\"home-prod\">{9}</select></label>\n        <label>倍率 <input id=\"home-prodk\" type=\"number\" inputmode=\"decimal\" min=\"{10}\" max=\"{11}\" step=\"any\" value=\"{12}\" {13}></label></div>\n      {14}\n      {15}</section>\n    <section><h3>試合</h3>\n      <div class=\"row\"><label>終わりの年 <select id=\"home-end\">{16}</select></label></div>\n      <div class=\"row\"><span class=\"muted\">挑戦 (選ばなくてもよい)</span>{17}</div>\n      {18}</section>\n    <div class=\"hgo\">{19}\n      <button class=\"big\" data-home=\"new\">{20}</button></div>": "<section><h3>Galaxy</h3>\n      <div class=\"row\"><label>Star map <select id=\"home-galaxy\"><option value=\"real\" {0}>Real stars (default)</option><option value=\"gen\" {1}>Generated</option></select></label></div>\n      <div class=\"row\"><label>Galaxy number <input id=\"home-seed\" type=\"text\" inputmode=\"numeric\" placeholder=\"Random if blank\" value=\"{2}\"></label>\n        <label><input id=\"home-spectate\" type=\"checkbox\" {3}> Spectate mode</label></div>\n      {4}</section>\n    <section><h3>Nations</h3>\n      <div class=\"row\"><label>Number of nations <select id=\"home-nat\">{5}</select></label>\n        <label>Difficulty <select id=\"home-hc\">{6}</select></label></div>\n      {7}\n      {8}</section>\n    <section><h3>Economy</h3>\n      <div class=\"row\"><label>Productivity <select id=\"home-prod\">{9}</select></label>\n        <label>Multiplier <input id=\"home-prodk\" type=\"number\" inputmode=\"decimal\" min=\"{10}\" max=\"{11}\" step=\"any\" value=\"{12}\" {13}></label></div>\n      {14}\n      {15}</section>\n    <section><h3>Match</h3>\n      <div class=\"row\"><label>End year <select id=\"home-end\">{16}</select></label></div>\n      <div class=\"row\"><span class=\"muted\">Challenges (optional)</span>{17}</div>\n      {18}</section>\n    <div class=\"hgo\">{19}\n      <button class=\"big\" data-home=\"new\">{20}</button></div>",
