"<section><h3>セーブスロット</h3>{0}</section>\n    <section><h3>ファイル</h3><div class=\"row\"><button data-home=\"export\">ファイルに書き出し</button><button data-home=\"import\">ファイルから読み込み</button></div></section>\n    <section><h3>クラウドのセーブ</h3><div class=\"row\"><div class=\"info\">アカウントにログインすると、別の端末のセーブも読める。</div><button data-home=\"tab\" data-t=\"account\" data-from=\"load\">アカウント{1}</button></div></section>\n    {2}": "<section><h3>Save slots</h3>{0}</section>\n    <section><h3>File</h3><div class=\"row\"><button data-home=\"export\">Export to file</button><button data-home=\"import\">Import from file</button></div></section>\n    <section><h3>Cloud saves</h3><div class=\"row\"><div class=\"info\">Sign in to an account to load saves from other devices.</div><button data-home=\"tab\" data-t=\"account\" data-from=\"load\">Account{1}</button></div></section>\n    {2}",
